-- Hosil X demo ma'lumotlar. Birinchi (eng eski) profil egasi bo'ladi.
-- Hammasi [DEMO] deb belgilangan; ishga tushirishdan oldin o'chiring.
do $$
declare v uuid := (select id from public.profiles order by created_at limit 1);
begin
  if v is null then raise exception 'Avval ro''yxatdan o''ting (profil topilmadi)'; end if;
end $$;
